import csv

# Check the output file for RFC 4180 compliance
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    rows = list(reader)

header = rows[0]
print(f"Header columns: {len(header)}")

# Check each row
errors = []
for i, row in enumerate(rows):
    if len(row) != len(header):
        errors.append(f"Row {i} has {len(row)} columns, expected {len(header)}")
    # Check for any fields that should be quoted but aren't
    for j, field in enumerate(row):
        # Check if field contains comma, double quote, or newline
        if ',' in field or '"' in field or '\n' in field:
            if not field.startswith('"') or not field.endswith('"'):
                errors.append(f"Row {i}, col {j}: field '{field}' should be quoted")

if errors:
    print("Errors found:")
    for e in errors[:20]:
        print(f"  {e}")
else:
    print("All rows are RFC 4180 compliant!")

# Check for fields that should be quoted
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='', encoding='utf-8') as f:
    content = f.read()

# Look for any field with comma that isn't quoted
lines = content.split('\n')
for i, line in enumerate(lines[:10]):
    print(f"Line {i}: {repr(line)}")

# Check a line with a comma in the city name
for i, line in enumerate(lines):
    if 'Gran Canaria' in line:
        print(f"Line with Gran Canaria: {repr(line)}")
        break
